<script setup>
import RecordPagination from './ui/RecordPagination.vue'
import {usePagination} from '../usePagination.js'
import {computed,ref} from 'vue'
import {useLearning} from '../useLearning.js'
import {icon} from '../assets.js'
const emit=defineEmits(['edit','archive','restore'])
const {state}=useLearning()
const filter=ref('all'),sort=ref('recent'),layout=ref('grid'),archived=ref(false)
const entries=computed(()=>(archived.value?state.boot?.archived_notes||[]:state.boot?.notes||[]).filter(n=>[n.title,n.text].join(' ').toLowerCase().includes(state.query.trim().toLowerCase())).filter(n=>filter.value==='all'||filter.value==='project'&&n.title.startsWith('项目记录｜')||filter.value==='linked'&&!!n.session_id||filter.value==='free'&&!n.session_id).slice().sort((a,b)=>sort.value==='recent'?b.updated_at.localeCompare(a.updated_at):a.updated_at.localeCompare(b.updated_at)))
const {page:notePage,items:noteRows}=usePagination(entries,()=>[filter.value,sort.value,archived.value,state.query])
</script>
<template><section class="notes-garden-live"><div class="notes-garden-toolbar"><div class="studio-pills"><button v-for="[key,label] in [['all','全部笔记'],['linked','来自目标'],['free','独立笔记'],['project','项目记录']]" :key="key" :class="{active:filter===key}" @click="filter=key">{{ label }}</button></div><div><button class="text-button" @click="archived=!archived">{{ archived?'返回当前笔记':'已归档' }}</button><select v-model="sort" aria-label="笔记排序"><option value="recent">最近编辑</option><option value="oldest">较早编辑</option></select><button :aria-pressed="layout==='grid'" class="icon-button" aria-label="卡片视图" @click="layout='grid'"><img :src="icon('grid')" alt=""></button><button :aria-pressed="layout==='list'" class="icon-button" aria-label="列表视图" @click="layout='list'"><img :src="icon('menu')" alt=""></button></div></div><div :class="['notes-garden-entries',layout]"><article v-for="(note,index) in noteRows" :key="note.id"><img v-if="layout==='grid'" class="note-garden-cover" :src="index%2?'/assets/feature-pages/scenes/notes-scene.png.webp':'/assets/split-elements/scenes/notes-card-scene.png.webp'" alt=""><div><span class="note-source-label">{{ note.title.startsWith('项目记录｜')?'项目记录':note.session_id?'关联学习目标':'独立笔记' }}</span><h2>{{ note.title }}</h2><p>{{ note.text }}</p><footer><small>{{ new Date(note.updated_at).toLocaleString('zh-CN') }}</small><button v-if="archived" class="text-button" @click="emit('restore',note.id)">恢复</button><template v-else><button class="text-button" @click="emit('edit',note)">继续编辑</button><button class="text-button" @click="emit('archive',note.id)">归档</button></template></footer></div></article><section v-if="!archived" class="note-garden-invite"><img src="/assets/split-elements/elements/memory-sprout.compact.webp" alt=""><h2>{{ entries.length?'再留下一颗思考的种子。':'每一个念头，都可以从这里生长。' }}</h2><p>记录自己的理解、疑问和任何有意思的想法。</p><button class="primary-button" @click="emit('edit')">{{ entries.length?'写一则新笔记':'写下第一则笔记' }}</button></section></div><RecordPagination v-model="notePage" :total="entries.length" label="笔记"/><div v-if="archived&&!entries.length" class="studio-empty-soft"><h3>没有匹配的归档笔记</h3><p>归档后保留的笔记，可以从这里恢复。</p></div></section></template>
